import { loadAppData, saveAppData } from '@storage/appStorage';
import { getState, setState } from './store';
import { createDefaultProfile } from '@config/defaultData';
import { logger } from '@utils/logger';

export async function loadInitialState() {
  logger.debug('Loading initial state');
  let data = await loadAppData();

  if (data) {
    setState({
      currentProfileId: data.activeProfileId || null,
      globalSettings: data.globalSettings || {
        autoInflect: true,
        voiceSettings: { rate: 1, pitch: 1, voiceURI: '' },
      },
      profiles: data.profiles || [],
    });

    const state = getState();
    const profile = state.profiles.find((p) => p.id === state.currentProfileId);
    if (profile) {
      setState({
        modeOrder: profile.modeOrder || [],
        hiddenModes: profile.hiddenModes || [],
      });
      logger.debug(`Loaded profile: ${profile.id} (${profile.name})`);
    }
  } else {
    logger.info('No data found, creating default profile');
    const defaultProfile = createDefaultProfile('Мой профиль', '🧑');
    const newData = {
      profiles: [defaultProfile],
      activeProfileId: defaultProfile.id,
      globalSettings: {
        autoInflect: true,
        voiceSettings: { rate: 1, pitch: 1, voiceURI: '' },
      },
      activityStates: {},
    };
    await saveAppData(newData);
    setState({
      profiles: newData.profiles,
      currentProfileId: newData.activeProfileId,
      globalSettings: newData.globalSettings,
      modeOrder: defaultProfile.modeOrder || [],
      hiddenModes: defaultProfile.hiddenModes || [],
    });
    logger.info(`Default profile created: ${defaultProfile.id}`);
  }
  logger.debug('Initial state loaded');
  return getState();
}

export async function savePersistentState() {
  logger.debug('Saving persistent state');
  const state = getState();
  const data = (await loadAppData()) || { profiles: [] };
  data.activeProfileId = state.currentProfileId;
  data.globalSettings = state.globalSettings;
  data.profiles = state.profiles;
  await saveAppData(data);
  logger.debug('Persistent state saved');
}

export function getActiveProfile() {
  const state = getState();
  const profile = state.profiles.find((p) => p.id === state.currentProfileId) || null;
  if (profile) {
    logger.debug(`getActiveProfile: ${profile.id} (${profile.name})`);
  } else {
    logger.warn('getActiveProfile: no active profile');
  }
  return profile;
}

store.js.content:
let state = {
  currentProfileId: null,
  currentMode: 'say',
  previousMode: null,
  editingMode: false,
  currentCategoryId: null,
  sentenceWords: [],
  profiles: [],
  globalSettings: {
    autoInflect: true,
    voiceSettings: { rate: 1, pitch: 1, voiceURI: '' },
  },
  activityState: null,
};

const subscribers = [];

export function getState() {
  return state;
}

export function setState(updates) {
  const changed = {};
  for (const key in updates) {
    if (state[key] !== updates[key]) {
      state[key] = updates[key];
      changed[key] = updates[key];
    }
  }
  if (Object.keys(changed).length) {
    subscribers.forEach((cb) => cb(changed, state));
  }
  return changed;
}

export function subscribe(callback) {
  subscribers.push(callback);
  return () => {
    const idx = subscribers.indexOf(callback);
    if (idx !== -1) subscribers.splice(idx, 1);
  };
}

appStorage.js.content:
// src/storage/appStorage.js
import { getDB } from './db';
import { logger } from '@utils/logger';

export async function loadAppData() {
  try {
    logger.debug('Loading app data from IndexedDB');
    const db = await getDB();
    const data = await db.get('appData', 'main');
    logger.debug(`App data loaded: ${data ? 'found' : 'not found'}`);
    return data?.value || null;
  } catch (e) {
    logger.error('loadAppData error:', e);
    return null;
  }
}

export async function saveAppData(value) {
  try {
    logger.debug('Saving app data to IndexedDB');
    const db = await getDB();
    await db.put('appData', { key: 'main', value });
    logger.debug('App data saved successfully');
    return true;
  } catch (e) {
    logger.error('saveAppData error:', e);
    return false;
  }
}

export async function saveProfile(profile) {
  logger.debug(`Saving profile: ${profile.id} (${profile.name})`);
  const data = await loadAppData();
  if (!data) {
    logger.error('saveProfile: no app data');
    return false;
  }
  const idx = data.profiles.findIndex(p => p.id === profile.id);
  if (idx >= 0) {
    data.profiles[idx] = profile;
  } else {
    data.profiles.push(profile);
  }
  logger.debug(`Profile ${profile.id} saved (${idx >= 0 ? 'updated' : 'added'})`);
  return saveAppData(data);
}

export async function deleteProfile(id) {
  logger.debug(`Deleting profile: ${id}`);
  const data = await loadAppData();
  if (!data) {
    logger.error('deleteProfile: no app data');
    return false;
  }
  data.profiles = data.profiles.filter(p => p.id !== id);
  logger.debug(`Profile ${id} deleted`);
  return saveAppData(data);
}

db.js.content:
import { openDB } from 'idb';

let dbPromise = null;

export async function getDB() {
  if (!dbPromise) {
    dbPromise = openDB('RASGovorilkaDB', 1, {
      upgrade(db) {
        if (!db.objectStoreNames.contains('appData')) {
          db.createObjectStore('appData', { keyPath: 'key' });
        }
        if (!db.objectStoreNames.contains('images')) {
          db.createObjectStore('images', { keyPath: 'id' });
        }
      },
    });
  }
  return dbPromise;
}

