/* ============================================================
   ПОЛЯ ВВОДА, SELECT, TEXTAREA
   ============================================================ */

input[type="text"],
input[type="number"],
input[type="time"],
input[type="password"],
textarea,
select {
  padding: 8px 12px;
  padding-left: 16px;
  border-radius: var(--radius-sm);
