  width: 100%;
  box-sizing: border-box;
}

select {
  appearance: auto;
  -webkit-appearance: auto;
  background-image: none;
}

select:focus,
input:focus,
textarea:focus {
  border-color: var(--primary);
  outline: none;
  box-shadow: 0 0 0 3px rgba(76, 175, 80, 0.2);
}

textarea {
  resize: vertical;
  min-height: 80px;
}

/* ============================================================
   СТИЛИЗАЦИЯ ПОЛЗУНКОВ (RANGE)
   ============================================================ */

/* Общий контейнер для строки с ползунком */
.form-row:has(input[type="range"]) {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
}

.form-row:has(input[type="range"]) label {
  min-width: 80px;
  flex-shrink: 0;
}

.form-row:has(input[type="range"]) input[type="range"] {
  flex: 1;
  min-width: 0;
}

.form-row:has(input[type="range"]) span {
  min-width: 32px;
  text-align: right;
  font-weight: 500;
  color: var(--text-secondary);
  flex-shrink: 0;
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  background: var(--border);
  border-radius: 3px;
  outline: none;
  transition: background 0.2s;
  padding: 0;
  border: none;
  min-height: auto;
}

/* Трек в Chrome/Safari/Edge */
input[type="range"]::-webkit-slider-runnable-track {
  height: 6px;
  background: var(--border);
  border-radius: 3px;
}

/* Трек в Firefox */
input[type="range"]::-moz-range-track {
  height: 6px;
  background: var(--border);
  border-radius: 3px;
  border: none;
}

/* Ползунок (thumb) в Chrome/Safari/Edge */
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  background: var(--primary);
  border-radius: 50%;
  cursor: pointer;
  margin-top: -7px;
  border: 2px solid var(--surface);
  box-shadow: var(--shadow);
  transition: background 0.2s, transform 0.1s;
}

/* Ползунок (thumb) в Firefox */
input[type="range"]::-moz-range-thumb {
  width: 20px;
  height: 20px;
  background: var(--primary);
  border-radius: 50%;
  cursor: pointer;
  border: 2px solid var(--surface);
  box-shadow: var(--shadow);
}

/* Ховер для ползунка */
input[type="range"]::-webkit-slider-thumb:hover {
  background: var(--primary-dark);
  transform: scale(1.05);
}

input[type="range"]::-moz-range-thumb:hover {
  background: var(--primary-dark);
  transform: scale(1.05);
}

/* Фокус – подсветка трека */
input[type="range"]:focus::-webkit-slider-runnable-track {
  background: var(--primary-light);
}

input[type="range"]:focus::-moz-range-track {
