  overflow-y: auto;
  padding: var(--grid-padding, var(--spacing-sm));
  background: var(--surface);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  margin: var(--spacing-sm) var(--spacing-md) var(--spacing-sm) var(--spacing-md);
  min-height: 0;
}

/* Когда есть нижняя панель – добавляем отступ снизу для grid-container */
.main-area.has-panel .grid-container {
  margin-bottom: calc(130px + var(--keyboard-offset, 0px));
}

/* Нижняя панель – фиксируется внизу */
.bottom-panel {
  flex-shrink: 0;
  background: var(--bg);
  padding: var(--spacing-sm) var(--spacing-md);
  padding-bottom: calc(var(--spacing-sm) + env(safe-area-inset-bottom, 0px));
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
  border-top: 1px solid var(--border);
  transition: transform 0.2s ease;
}

/* При открытии клавиатуры панель поднимается вместе с ней */
.keyboard-open .bottom-panel {
  transform: translateY(calc(-1 * var(--keyboard-offset, 0px)));
}

/* Если панель скрыта – убираем её */
.bottom-panel.hidden {
  display: none !important;
}

modal.css.content:
/* ============================================================
   МОДАЛКИ
   ============================================================ */

.modal {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.25s ease, visibility 0.25s ease;
  backdrop-filter: blur(2px);
  padding: var(--spacing-lg);
}

.modal.visible {
  opacity: 1;
  visibility: visible;
}

.modal-content {
  background: var(--surface);
  width: 100%;
  max-width: 600px;
  max-height: 95vh; /* увеличен с 90vh */
  border-radius: var(--radius);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.3);
}

.modal-header {
  padding: var(--spacing-lg) var(--spacing-xl) var(--spacing-md);
  border-bottom: 1px solid var(--border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-shrink: 0;
}

.modal-title-wrap {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
}

.modal-icon {
  font-size: 48px;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 64px;
  height: 64px;
  background: var(--primary-light);
  border-radius: var(--radius-sm);
  border: 2px solid var(--primary);
  box-shadow: var(--shadow);
}

.modal-header h3 {
  margin: 0;
  font-size: 20px;
}

.modal-body {
  flex: 1;
  overflow-y: auto;
  padding: var(--spacing-md) var(--spacing-xl); /* уменьшен вертикальный паддинг */
  display: flex;
  flex-direction: column;
  align-items: center;
}

.modal-body > * {
  width: 100%;
  max-width: 100%;
}

.modal-footer {
  padding: var(--spacing-md) var(--spacing-xl);
  border-top: 1px solid var(--border);
  display: flex;
  justify-content: flex-end;
  gap: var(--spacing-sm);
  flex-shrink: 0;
}

.btn-close {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: none;
  background: transparent;
  font-size: 24px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  transition: background 0.2s;
  color: var(--text-secondary);
}

.btn-close:hover {
  background: rgba(0, 0, 0, 0.05);
}

/* Превью иконки в редакторе профиля */
.profile-preview {
  display: flex;
  justify-content: center;
  margin-bottom: var(--spacing-md);
}

.profile-preview-icon {
  width: 80px;
  height: 80px;
  border-radius: var(--radius);
  background: var(--primary-light);
  border: 3px solid var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
  box-shadow: var(--shadow);
}

mode-bar.css.content:
