sentence-bar.css.content:
/* Строка предложения */
.sentence-bar {
  display: flex;
  align-items: center;
  background: var(--surface);
  border: 2px solid var(--primary);
  border-radius: 24px;
  overflow: hidden;
  min-height: 44px;
  width: 100%;
  box-shadow: var(--shadow);
}

.sentence-btn {
  flex-shrink: 0;
  min-width: 22px;
  min-height: 44px;
  border: none;
  cursor: pointer;
  font-size: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s, transform 0.1s;
  background: transparent;
  color: #fff;
}
.sentence-btn:active {
  transform: scale(0.92);
}
.sentence-btn-clear {
  background: var(--danger);
  border-radius: 4px;
}
.sentence-btn-speak {
  background: var(--primary);
  color: #000;
  border-radius: 4px;
}

.sentence-words-wrapper {
  flex: 1;
  overflow-x: auto;
  overflow-y: hidden;
  display: flex;
  flex-wrap: nowrap;
  gap: var(--spacing-xs);
  padding: var(--spacing-xs) var(--spacing-sm);
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  min-width: 0;
  background: var(--surface);
}
.sentence-words-wrapper::-webkit-scrollbar {
  height: 4px;
}
.sentence-words-wrapper::-webkit-scrollbar-thumb {
  background: var(--primary-light);
  border-radius: 2px;
}

.sentence-word {
  background: var(--primary-light);
  color: #000;
  padding: var(--spacing-xs) var(--spacing-md);
  border-radius: 30px;
  font-size: 16px;
  font-weight: 500;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-xs);
  transition: background 0.3s, transform 0.2s;
  flex-shrink: 0;
  white-space: nowrap;
}
.sentence-word:active {
  background: var(--primary);
}
.sentence-word.highlight {
  background: var(--primary) !important;
  color: #fff !important;
  transform: scale(1.1);
  box-shadow: 0 0 15px rgba(76, 175, 80, 0.6);
}

toast.css.content:
.toast-container {
  position: fixed;
  bottom: 80px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 2000;
  display: flex;
  flex-direction: column;
  gap: 8px;
  align-items: center;
  pointer-events: none;
}
.toast {
  background: rgba(0,0,0,0.8);
  color: #fff;
  padding: 8px 20px;
  border-radius: 30px;
  font-size: 14px;
  font-weight: 500;
  pointer-events: auto;
  animation: slideUp 0.3s ease;
  max-width: 90%;
}
.toast.error { background: var(--danger); }
.toast.success { background: var(--primary); }
@keyframes slideUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

toggle.css.content:
/* Переключатель */
.toggle-switch {
  position: relative;
  display: inline-block;
  width: 44px;
  height: 24px;
  flex-shrink: 0;
}
.toggle-switch input {
  opacity: 0;
  width: 0;
  height: 0;
  position: absolute;
}
.slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: #ccc;
  border-radius: 24px;
  transition: background var(--transition);
}
.slider::before {
  content: '';
  position: absolute;
  height: 18px;
  width: 18px;
  left: 3px;
  bottom: 3px;
  background: white;
  border-radius: 50%;
  transition: transform var(--transition);
}
.toggle-switch input:checked + .slider {
  background: var(--primary);
}
.toggle-switch input:checked + .slider::before {
  transform: translateX(20px);
}

